                return None

            # Get the link target
            target = links[candidate]
            if not isinstance(target, str):
                return None

            # Process the target
            if target.startswith('/'):
                # Absolute target: reset to root and process target components
                current = '/'
                target_components = target[1:].split('/') if len(target) > 1 else []
